"""Synthetic cross-account and cross-device tracking; never calls production services."""
import asyncio,json
from playwright.async_api import async_playwright
async def login(ctx,name):
 p=await ctx.new_page();await p.goto('http://127.0.0.1:8010');await p.locator('input[type=text]').first.fill(name);await p.locator('input[type=password]').fill('PruebaSegura123!');await p.get_by_role('button',name='Iniciar Sesión',exact=True).click();await p.locator('nav.sidebar').wait_for();await p.wait_for_function('window.SICIPSeguimiento');return p
async def main():
 async with async_playwright() as pw:
  b=await pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);admin=await b.new_context(viewport={'width':1440,'height':1000});await admin.route('https://**/*',lambda r:r.abort());a=await login(admin,'TESTADMIN');errors=[];a.on('pageerror',lambda e:errors.append(str(e)));await a.wait_for_timeout(1400)
  assert await a.locator('nav.sidebar').get_by_role('button',name='Reportes',exact=True).count()==0
  menu=await a.locator('nav.sidebar>div').first.evaluate("n=>Array.from(n.children).map(c=>({text:(c.querySelector('button')||c).textContent.trim(),y:c.getBoundingClientRect().y})).filter(x=>x.text)")
  y=lambda text:next(r['y']for r in menu if text in r['text']);assert y('Mis Trámites')<y('Solicitudes')<y('Jefe de Servicio')<y('Departamento de Personal')<y('Administración'),menu
  await a.evaluate("sessionStorage.setItem('sicip_usuario',JSON.stringify({...window.SICIPCentral.user,nombre:'DEL TORO/DE LA CRUZ/ANA MARÍA'}));dispatchEvent(new Event('sicip:session-update'))");await a.locator('.sicip-flow-profile h3').get_by_text('ANA MARÍA DEL TORO DE LA CRUZ',exact=True).wait_for();assert 'ANA MARÍA DEL TORO DE LA CRUZ'in await a.locator('#root>div>header').inner_text();print('Menú sin Reportes, agrupación solicitada y nombre compuesto en orden correcto.',flush=True)
  jefe=await b.new_context();await jefe.route('https://**/*',lambda r:r.abort());j=await login(jefe,'TESTJEFE');payload={'tipo':'TIEMPO_EXTRA','motivo':'VACACIONES','titular':'TESTADMIN','suplente':'TESTUSER','plaza':'101','inicio':'2026-05-01','fin':'2026-05-15','unidad':'Unidad de prueba','servicio':'Servicio','horario_codigo':'104','horario':'6:00 a 14:00','horas_dia':8,'firmante_jefe':'TESTADMIN','firmante_dependencia':'TESTUSER'}
  record=await j.evaluate("async payload=>{const s=window.SICIPCentral;let r=await s.api('/api/contratacion',{method:'POST',body:JSON.stringify({request_key:crypto.randomUUID(),corte:'22222222-2222-4222-8222-222222222222',payload})});return s.api('/api/contratacion/'+r.uuid+'/accion',{method:'POST',body:JSON.stringify({version:r.version,accion:'ENVIAR'})})}",payload)
  pase=await a.evaluate("async()=>{const s=window.SICIPCentral,f=await s.api('/api/pases/folio',{method:'POST',body:JSON.stringify({request_id:crypto.randomUUID()})});return s.api('/api/pases/registros',{method:'POST',body:JSON.stringify({folio:f.folio,matricula:'TESTUSER',nombre:'Trabajador de prueba',fecha:'2026-05-01',estado:'PENDIENTE_ENTREGA'})});}")
  worker=await b.new_context(viewport={'width':1440,'height':1000});await worker.route('https://**/*',lambda r:r.abort());w=await login(worker,'TESTUSER');w.on('pageerror',lambda e:errors.append(str(e)));await w.locator('nav.sidebar').get_by_role('button',name='Mis Trámites',exact=True).click();await w.locator('[data-tracking]').get_by_text(record['folio'],exact=True).wait_for();await w.locator('[data-tracking]').get_by_text(pase['folioCorto'],exact=True).wait_for();assert 'Sin acuse de entrega'in await w.locator('[data-tracking]').inner_text();assert not await w.locator('[data-tracking]').get_by_role('button',name='Recibir',exact=True).count();print('El trabajador ve tiempo extra creado por el jefe y pase creado por otra cuenta en otro navegador.',flush=True)
  for folio in [record['folio'],pase['folioCorto']]:await a.evaluate("async f=>window.SICIPCentral.api('/api/seguimiento/recepcion',{method:'POST',body:JSON.stringify({folio:f,matricula:'TESTUSER'})})",folio)
  await w.locator('[data-refresh]').click();await w.wait_for_function("Array.from(document.querySelectorAll('[data-tracking] tbody tr')).filter(r=>r.textContent.includes('Entrega registrada en Personal')).length>=2");assert 'Sin registro de pago'in await w.locator('[data-tracking]').inner_text();
  for folio in [record['folio'],pase['folioCorto']]:assert 'Entrega registrada en Personal'in await w.locator('[data-tracking] tbody tr').filter(has_text=folio).inner_text()
  await a.evaluate("history.pushState({},'', '/recepciones');dispatchEvent(new PopStateEvent('popstate'))");await a.locator('#sicip-recep-folio-input').wait_for(state='attached');await a.evaluate('window.__SICIP_RECEP_SHOW_FOLIO__()');await a.locator('#sicip-recep-folio-input').wait_for();await a.locator('#sicip-recep-folio-input').fill(pase['folioCorto']);await a.evaluate('window.__SICIP_RECEP_FOLIO_SEARCH__()');await a.locator('#sicip-recep-folio-result').get_by_text('Trabajador de prueba',exact=False).first.wait_for();print('Recepción resuelve el folio central desde otro equipo; entrega visible sin confundirla con pago.',flush=True)
  await w.screenshot(path='/workspace/sicip-env/mis-tramites-desktop.png');await w.set_viewport_size({'width':390,'height':844});assert await w.evaluate('document.documentElement.scrollWidth<=innerWidth+1');await w.screenshot(path='/workspace/sicip-env/mis-tramites-mobile.png');assert not errors,errors;await b.close()
asyncio.run(main())
